-- Seed: exercise database generated from docs/Uebungsdatenbank.xlsx
-- Do not edit by hand: change the xlsx and run supabase/seed/generate_exercises.py
-- Re-run safe: existing IDs are updated.
begin;
set constraints all deferred;
on conflict (id) do update set
  name = excluded.name, base = excluded.base, pattern = excluded.pattern,
  primary_muscle = excluded.primary_muscle, secondary = excluded.secondary,
  equipment = excluded.equipment, unilateral = excluded.unilateral,
  tracking_type = excluded.tracking_type, level = excluded.level,
  alt1 = excluded.alt1, alt2 = excluded.alt2, video_url = excluded.video_url,
  hint = excluded.hint, active = excluded.active, sort = excluded.sort;
commit;
